            last = runs([grid[r][-1] for r in range(h)])

        matches = [(a, b) for a in first for b in last
                   if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]]
        if matches:
            a, b = max(matches, key=lambda p: p[0][2] - p[0][1])
            pair = (axis, a, b)
            break

    if pair is None:
        return out

    axis, a, b = pair
    bar_color = a[0]
    a0, a1 = a[1], a[2]
    b0, b1 = b[1], b[2]
    length = a1 - a0

    markers = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != bar_color]

    for r, c, color in markers:
        if axis == "horizontal":
            if a0 <= c < a1:
                offset = c - a0
                # From the marker toward the first (top) edge.
                for rr in range(r - 1, -1, -1):
                    if out[rr][c] == bg:
                        out[rr][c] = color
                target = b0 + offset
                # Continue from the opposite (bottom) edge across the grid.
                for rr in range(h - 1, -1, -1):
                    if out[rr][target] == bg:
                        out[rr][target] = color
            elif b0 <= c < b0 + length:
                offset = c - b0
                # From the marker toward the second (bottom) edge.
                for rr in range(r + 1, h):
                    if out[rr][c] == bg:
                        out[rr][c] = color
                target = a0 + offset
                # Continue from the opposite (top) edge across the grid.
                for rr in range(h):
                    if out[rr][target] == bg:
                        out[rr][target] = color
        else:
            if a0 <= r < a1:
                offset = r - a0
                for cc in range(c - 1, -1, -1):
                    if out[r][cc] == bg:
                        out[r][cc] = color
                target = b0 + offset
                for cc in range(w - 1, -1, -1):
                    if out[target][cc] == bg:
                        out[target][cc] = color
            elif b0 <= r < b0 + length:
                offset = r - b0
                for cc in range(c + 1, w):
                    if out[r][cc] == bg:
                        out[r][cc] = color
                target = a0 + offset
                for cc in range(w):
                    if out[target][cc] == bg:
                        out[target][cc] = color

    for r, c, _ in markers:
        out[r][c] = 4

    return out
